import refrom django.db.models import Ffrom django.http import JsonResponsefrom django.shortcuts import get_object_or_404, redirectfrom django.urls import reversefrom .models import AndroidAppfrom django.http import FileResponse, JsonResponsefrom django.shortcuts import get_object_or_404import osdef latest_version(request):    """    Checks the client's current application version code against the     latest active database entry to determine if an update is available.    """    user_agent = request.META.get("HTTP_USER_AGENT", "")    # Basic system validation    if "android" not in user_agent.lower():        return JsonResponse(            {                "status": False,                "message": "Android device required."            },            status=403,        )    # Fetch the latest active application version from database    app = (        AndroidApp.objects        .filter(is_active=True)        .order_by("-version_code")        .first()    )    if not app:        return JsonResponse(            {                "status": False,                "message": "No active APK found."            },            status=404,        )    client_version = 0    client_version_raw = request.GET.get("version_code")    # 1. First Priority: Extract version code from the URL parameters (?version_code=X)    if client_version_raw is not None:        try:            client_version = int(client_version_raw)        except ValueError:            client_version = 0                # 2. Second Priority/Fallback: Extract 'VersionCode=X' custom token out of User-Agent    else:        version_match = re.search(r"VersionCode=(\d+)", user_agent, re.IGNORECASE)        if version_match:            try:                client_version = int(version_match.group(1))            except (ValueError, IndexError):                client_version = 0    # If the user is running an equal or newer package version, do not prompt them    if client_version >= app.version_code:        return JsonResponse({            "status": True,            "update_available": False,            "message": "You are using the latest version.",            "current_version": app.version_name,            "current_version_code": app.version_code,        })    # If an update is required    return JsonResponse({        "status": True,        "update_available": True,        "version_name": app.version_name,        "version_code": app.version_code,        "force_update": app.force_update,        "release_notes": app.release_notes,        "apk_size": app.apk_size,        "download_count": app.download_count,        "download_url": request.build_absolute_uri(            reverse("download_apk", args=[app.pk])        ),    })def download_apk(request, pk):    user_agent = request.META.get("HTTP_USER_AGENT", "")    if "android" not in user_agent.lower():        return JsonResponse(            {"status": False, "message": "APK download is allowed only on Android devices."},            status=403,        )            app = get_object_or_404(AndroidApp, pk=pk, is_active=True)        if not app.apk:        return JsonResponse(            {"status": False, "message": "APK file not found."},            status=404,        )            # Atomic database increment    AndroidApp.objects.filter(pk=app.pk).update(download_count=F("download_count") + 1)        # Open the file object    apk_file = app.apk.open('rb')    filename = os.path.basename(app.apk.name)        # Use built-in attachment handlers to structure content headers automatically    response = FileResponse(        apk_file,         as_attachment=True,         filename=filename,        content_type='application/vnd.android.package-archive'    )        # Explicitly calculate file size so custom Android services don't drop the stream    response['Content-Length'] = app.apk.size        return response    